import {downloadAccountArchive} from './account-archive-export.mjs';
import {toolBanner} from './tool-banner.mjs';
import {keys,write} from './state.mjs';
import {esc,icon,download} from './ui.mjs';
import {defaults,normalizeSettings} from './settings-model.mjs';
import {withStableView} from './view-stability.mjs';
const $=s=>document.querySelector(s);let session;
export function clearSettingsWork(){session?.exportController?.abort();session=null;}
export const settingsHasWork=()=>!!(session&&(session.dirty||session.busy));
export function settingsRouteGuard(target){if(!session)return true;const s=session;if(s.busy){s.ctx.notify('正在处理账户资料，请稍候。');return false;}if(!s.dirty)return true;s.ctx.modal('设置尚未保存','<p class="hub-description">离开前，可以保存这次修改，或放弃修改。</p><div class="settings-actions"><button class="btn secondary" id="settings-stay">继续设置</button><button class="btn secondary" id="settings-discard">放弃修改</button><button class="btn primary" id="settings-save-leave">保存并离开</button></div>');$('#settings-stay').onclick=()=>$('#workspace-dialog').close();$('#settings-discard').onclick=()=>{if(session!==s)return;s.dirty=false;$('#workspace-dialog').close();location.hash=target;};$('#settings-save-leave').onclick=()=>{if(save(s)){ $('#workspace-dialog').close();location.hash=target;}};return false;}
window.addEventListener('beforeunload',e=>{if(settingsHasWork()){e.preventDefault();e.returnValue='';}});
const categoryKeys=tab=>tab==='writing'?['degree','major']:tab==='notifications'?['localActivityEnabled']:['density','fontSize','theme'];
function storedSettings(){const raw=localStorage.getItem(keys.preferences);if(raw===null)return {};let value;try{value=JSON.parse(raw);}catch{throw Error('已保存的偏好无法读取，已停止覆盖。请先保留浏览器数据并联系支持。');}if(!value||typeof value!=='object'||Array.isArray(value))throw Error('已保存的偏好结构异常，已停止覆盖。请先保留浏览器数据并联系支持。');return value;}
function save(s){if(session!==s)return false;try{if(s.storageError)throw Error(s.storageError);const latest=storedSettings(),normalized=normalizeSettings(latest),changed=categoryKeys(s.tab).filter(key=>s.values[key]!==s.original[key]);if(changed.some(key=>normalized[key]!==s.original[key]&&normalized[key]!==s.values[key]))throw Error('这些设置已在其他窗口修改，已停止覆盖。请记下当前选择，再重新打开设置核对。');const next={...latest};for(const key of changed)next[key]=s.values[key];write(keys.preferences,next);s.values=normalizeSettings(next);s.original={...s.values};s.dirty=false;withStableView($('.dashboard'),()=>s.ctx.apply());status('设置已保存 · 仅应用于当前浏览器');s.ctx.notify('设置已保存。');return true;}catch(error){status(error.message?.includes('已停止覆盖')?error.message:'保存失败，请检查浏览器存储空间；当前选择仍保留。',true);return false;}}
function status(message,error=false){const el=$('#settings-status');if(el){el.textContent=message;el.classList.toggle('error',error);}}
function preview(s){if(session!==s)return;return withStableView($('.dashboard'),()=>{const box=$('#settings-example');if(box){box.dataset.density=s.values.density;box.dataset.font=s.values.fontSize;box.dataset.theme=s.values.theme;}s.dirty=JSON.stringify(s.values)!==JSON.stringify(s.original);status(s.storageError|| (s.dirty?'有未保存的修改':'设置已保存于当前浏览器'),!!s.storageError);});}
const choice=(name,value,label,description,current)=>`<label class="settings-choice"><input type="radio" name="${name}" value="${value}" ${current===value?'checked':''}><span><b>${label}</b>${description?`<small>${description}</small>`:''}</span></label>`;
export function mountSettings(ctx,section){clearSettingsWork();const tab=section==='privacy'||section==='data'?'data':['writing','shortcuts','notifications'].includes(section)?section:'interface';let values=normalizeSettings(),storageError='';if(tab!=='data')try{values=normalizeSettings(storedSettings());}catch(error){storageError=error.message;}const s=session={ctx,tab,values,original:{...values},dirty:false,busy:false,storageError};$('.dashboard').onclick=null;$('.dashboard').innerHTML=`${toolBanner('settings',{title:'设置中心',description:'管理账户、研究偏好与数据，让工作空间适合你的习惯。',actions:`<span class="settings-local">${icon('shield',16)} ${tab==='data'?'账户数据管理':'当前设备生效'}</span>`})}<div class="settings-layout"><nav class="settings-side-nav" aria-label="设置分类"><div class="settings-nav-header"><b>工作空间设置</b><small>管理你的研究环境</small></div><div class="settings-nav-group"><span class="settings-nav-label">账户</span><a href="#account">${icon('user',18)}<span>账户与安全</span>${icon('arrow',14)}</a><a href="#membership">${icon('diamond',18)}<span>服务与用量</span>${icon('arrow',14)}</a></div><div class="settings-nav-group"><span class="settings-nav-label">工作习惯</span><a href="#settings/writing" data-settings-tab="writing" ${tab==='writing'?'aria-current="page"':''}>${icon('pen',18)}<span>研究偏好</span>${icon('arrow',14)}</a><a href="#settings" data-settings-tab="interface" ${tab==='interface'?'aria-current="page"':''}>${icon('grid',18)}<span>界面与体验</span>${icon('arrow',14)}</a><a href="#settings/shortcuts" data-settings-tab="shortcuts" ${tab==='shortcuts'?'aria-current="page"':''}>${icon('menu',18)}<span>快捷键</span>${icon('arrow',14)}</a></div><div class="settings-nav-group"><span class="settings-nav-label">数据与通知</span><a href="#settings/notifications" data-settings-tab="notifications" ${tab==='notifications'?'aria-current="page"':''}>${icon('bell',18)}<span>通知设置</span>${icon('arrow',14)}</a><a href="#settings/data" data-settings-tab="data" ${tab==='data'?'aria-current="page"':''}>${icon('shield',18)}<span>数据与隐私</span>${icon('arrow',14)}</a></div><a class="settings-nav-help" href="#help">${icon('help',18)}<span>需要帮助？</span>${icon('arrow',14)}</a></nav><section class="card settings-main">${tab==='data'?dataPanel():tab==='shortcuts'?shortcutsPanel():tab==='notifications'?notificationPanel(s):preferencePanel(s)}</section></div><div id="settings-status" class="settings-status" role="status" aria-live="polite">设置已保存于当前浏览器</div>`;
if(tab==='data'){bindData(s);status('在当前账户中管理研究资料、云端文件与导出记录。');return;}if(tab==='shortcuts'){status('说明仅包含当前支持的键盘操作。');return;}$('#settings-form').oninput=()=>{s.values=normalizeSettings({...s.values,...Object.fromEntries(new FormData($('#settings-form'))),...(tab==='notifications'?{localActivityEnabled:$('#setting-local-activity').checked}:{})});preview(s);};$('#settings-form').onsubmit=e=>{e.preventDefault();save(s);};$('#settings-reset').onclick=()=>{ctx.modal('恢复当前分类的默认设置','<p class="hub-description">只重置当前分类的偏好，不删除项目或成果。重置后需要点击保存。</p><button class="btn primary" id="confirm-settings-reset">恢复默认</button>');$('#confirm-settings-reset').onclick=()=>{if(session!==s)return;for(const key of categoryKeys(tab))s.values[key]=defaults[key];const f=$('#settings-form');for(const [key,value]of Object.entries(s.values)){const field=f.elements.namedItem(key);if(field){if(field.type==='checkbox')field.checked=value;else field.value=value;}}preview(s);$('#workspace-dialog').close();};};preview(s);}
function preferencePanel(s){return `<h2>${s.tab==='writing'?'研究偏好':'界面与体验'}</h2><p class="settings-description">${s.tab==='writing'?'设置常用学段与专业，减少重复填写。':'选择信息密度、阅读字号与主题。保存后应用于当前浏览器。'}</p><form id="settings-form" class="hub-form">${s.tab==='writing'?`<label for="setting-degree">默认学段</label><select name="degree" id="setting-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===s.values.degree?'selected':''}>${d}</option>`).join('')}</select><label for="setting-major">默认学科专业</label><input name="major" id="setting-major" maxlength="100" value="${esc(s.values.major)}" placeholder="例如：教育学"><p class="hub-footnote">只影响新建内容；每次任务仍可单独调整。</p>`:`<fieldset><legend>列表显示密度</legend><div class="settings-choices">${choice('density','comfortable','舒适','留白充足，便于浏览',s.values.density)}${choice('density','compact','紧凑','更集中地查看记录',s.values.density)}</div></fieldset><fieldset><legend>界面字号</legend><div class="settings-choices font-choices">${choice('fontSize','normal','标准','',s.values.fontSize)}${choice('fontSize','large','较大','',s.values.fontSize)}${choice('fontSize','larger','更大','',s.values.fontSize)}</div></fieldset><fieldset><legend>主题模式</legend><div class="settings-choices theme-choices">${choice('theme','light','浅色','清晰明亮的工作空间',s.values.theme)}${choice('theme','dark','深色','降低夜间阅读刺激',s.values.theme)}${choice('theme','system','跟随系统','自动匹配设备设置',s.values.theme)}</div></fieldset><div class="settings-preview-title">效果预览 <small>示例内容，不会保存为项目</small></div><div id="settings-example"><header>最近项目 <span>预览</span></header><div>${icon('folder',24)}<span><b>我的毕业论文研究</b><small>本科 · 教育学 · 最近编辑</small></span><em>进行中</em></div><div>${icon('file',24)}<span><b>文献综述与研究框架</b><small>论文大纲 · 可继续编辑</small></span><em>草稿</em></div></div><p class="hub-footnote">预览仅作用于上方示例，保存后应用到工作空间。</p>`}<footer class="settings-actions"><button type="button" id="settings-reset" class="btn secondary">恢复默认</button><button class="btn primary" type="submit">保存设置</button></footer></form>`;}
function dataPanel(){return `<h2>数据与隐私</h2><p class="settings-description">项目、稿件、文件与任务统一在你的 PaperKnow 账户中管理，登录同一账户即可继续使用已保存的资料。</p><section class="settings-storage"><span>${icon('shield',24)}</span><div><b>统一账户 · 云端管理</b><p>研究项目与任务记录关联当前账户，上传原件和生成文件集中保存在私有文件空间。通过文件管理下载、整理或批量删除文件。</p></div></section><div class="settings-data-actions"><a class="btn secondary" href="#projects">管理研究项目 ${icon('arrow',15)}</a><a class="btn secondary" href="#assets">打开文件管理 ${icon('arrow',15)}</a><a class="btn secondary" href="#tasks">查看任务记录 ${icon('arrow',15)}</a></div><hr><section class="settings-account-export" aria-labelledby="settings-account-export-heading"><div class="settings-data-heading"><span class="settings-data-icon">${icon('file',22)}</span><div><h3 id="settings-account-export-heading">导出账户资料</h3><span class="help-pill">当前登录账户</span></div></div><p>下载当前账户的项目、已保存稿件、处理成果与修订、任务记录、本人反馈及文件清单，便于查阅和保管。</p><div class="settings-data-actions"><button class="btn secondary" type="button" id="settings-account-export">${icon('download',17)} 导出账户资料包</button><a href="#assets">下载原件与生成文件 ${icon('arrow',15)}</a></div><p id="settings-account-status" role="status" aria-live="polite"></p><small>资料包为 JSON 格式。原件文件与生成文件的实际内容需在文件管理中另外下载；未保存的输入不包含在资料包中。</small></section><section class="settings-privacy-note"><h3>访问与隐私</h3><p>账户资料通过登录身份与归属核对后访问。退出登录会结束当前会话，已保存的资料仍保留在账户中。</p><p>界面偏好、会话恢复标记和临时编辑缓存可能保留在当前设备，它们不构成独立账户。需要保留的编辑内容请及时保存。</p><p>在线任务处理本次选择并提交的材料；具体处理范围可在服务说明中查看。资料更正、账户注销或其他隐私问题，可联系支持核对处理。</p><div class="settings-data-actions"><a href="#account">账户与安全 ${icon('arrow',15)}</a><a href="/privacy/" target="_blank" rel="noopener noreferrer">隐私与数据说明 ↗</a><a href="#help">帮助与反馈 ${icon('arrow',15)}</a></div></section>`;}
function bindData(s){$('#settings-account-export').onclick=async()=>{if(session!==s||s.busy)return;s.busy=true;const button=$('#settings-account-export'),node=$('#settings-account-status'),controller=new AbortController();s.exportController=controller;const timer=setTimeout(()=>controller.abort(),60000);button.disabled=true;node.textContent='正在读取账户资料，请稍候…';node.classList.remove('error');try{const exported=await downloadAccountArchive({signal:controller.signal,isCurrent:()=>session===s&&node.isConnected});if(session!==s)return;node.textContent=exported.message;s.ctx.notify('已发起账户资料包下载，请检查下载文件。');}catch(error){if(session!==s)return;node.textContent=controller.signal.aborted?'账户资料导出已中断，未发起下载，请稍后重试。':error.message||'账户资料导出失败，请稍后重试。';node.classList.add('error');}finally{clearTimeout(timer);s.busy=false;if(s.exportController===controller)s.exportController=null;if(button.isConnected)button.disabled=false;}};}

function shortcutsPanel(){return `<h2>快捷键</h2><p class="settings-description">通过键盘完成浏览和常见操作。编辑器内的撤销、复制、粘贴遵循浏览器和系统行为。</p><table class="settings-shortcuts-table"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><kbd>Esc</kbd></td><td>关闭账户菜单、移动端导航或当前可关闭的对话框</td></tr><tr><td><kbd>Tab</kbd> / <kbd>Shift</kbd> + <kbd>Tab</kbd></td><td>在链接、按钮和表单输入框之间移动焦点</td></tr><tr><td><kbd>Enter</kbd></td><td>打开已聚焦的链接，或提交当前表单</td></tr><tr><td><kbd>Space</kbd></td><td>操作已聚焦的按钮或复选框</td></tr></tbody></table><p class="hub-footnote">暂未提供全局快速新建或自定义快捷键。离开有未保存内容的页面时，仍会提示你先确认。</p>`;}
function notificationPanel(s){return `<h2>通知与动态</h2><p class="settings-description">设置当前浏览器顶部“成果动态”的展示方式。</p><form id="settings-form" class="hub-form"><label class="settings-notification-option"><input type="checkbox" name="localActivityEnabled" id="setting-local-activity" ${s.values.localActivityEnabled?'checked':''}><span><b>显示本地成果动态</b><small>开启后，点击顶部通知图标可查看最近保存的本地成果。关闭后隐藏这些动态；不会删除任何成果。</small></span></label><p class="hub-footnote">此设置仅影响当前浏览器的本地成果动态。账户反馈处理状态在“帮助与反馈”的账户内容中查看；不发送邮件、短信或浏览器推送。</p><footer class="settings-actions"><button type="button" id="settings-reset" class="btn secondary">恢复默认</button><button class="btn primary" type="submit">保存设置</button></footer></form>`;}
